{
  "name": "claudinho",
  "version": "0.6.0",
  "description": "Live football in Claude Code for the competition you follow: the score or the countdown above the prompt (the same line on demand with /claudinho), a toast that says what happened (a goal and its scorer, full time and the result), a goal celebration with the Claude mascot, the live score beside your prompt for the model, all from the installed claudinho CLI's local cache, and a match pane with the match you follow, its goals and cards (/claudinho match, read by the CLI). Live data: ESPN. Not affiliated with FIFA, any confederation, league or club, or Anthropic.",
  "types": "./types/index.d.ts",
  "author": {
    "name": "Arturo Garrido"
  },
  "homepage": "https://github.com/arturogarrido/claudinho/tree/main/packages/plugin",
  "repository": "https://github.com/arturogarrido/claudinho",
  "license": "MIT",
  "userConfig": {
    "toasts": {
      "type": "string",
      "title": "Score toasts",
      "options": [
        "pinned",
        "all",
        "off"
      ],
      "default": "pinned",
      "description": "Which goals, score changes and full times raise a toast: pinned, your pinned team's match (claudinho follow <alias> --team <name>); with no pin saved, pinned toasts nothing. all, every live match of the competition you follow; off, none."
    },
    "celebrate": {
      "type": "string",
      "title": "Goal celebration",
      "options": [
        "on",
        "off"
      ],
      "default": "on",
      "description": "On a goal for your team the toasts announce (or any goal under all of a match with no pinned side), and at full time on its win or draw, the band plays a short celebration; off plays nothing."
    },
    "context": {
      "type": "string",
      "title": "Prompt context",
      "options": [
        "on",
        "off"
      ],
      "default": "on",
      "description": "While a match is live, each prompt you send carries the live score for Claude to read; off sends nothing with your prompts."
    },
    "language": {
      "type": "string",
      "title": "Language",
      "options": [
        "auto",
        "en",
        "es",
        "pt",
        "fr"
      ],
      "default": "auto",
      "description": "The language of the band, the toasts, the goal celebration and the match pane: en, es, pt or fr; auto follows CLAUDINHO_LANG, then LANG (es_MX.UTF-8 is es), else English. The terminal statusline and the live score for Claude stay English."
    }
  }
}
